css:
.progress {
  position: relative;
  display: grid;
  gap: 1.5rem;
}

.loader {
  /*default color*/
  --dcolor: 247, 212, 57; /*R, G, B*/

  /* message */
  --emessage: "Please wait";
  --xdelay: 0s;

  /*steps*/
  --tcount: 5;
  --esequence: 18s;
  /**/
  --rstep: calc(var(--esequence) / var(--tcount));
  --plays: 3;

  position: relative;
  display: flex;
  align-items: center;
  justify-content: start;
  gap: 1.5rem;
}

.loader:nth-child(1) {
  --xdelay: 0s;
}
.loader:nth-child(2) {
  --xdelay: var(--rstep);
}
.loader:nth-child(3) {
  --xdelay: calc(var(--rstep) * 2);
}
.loader:nth-child(4) {
  --xdelay: calc(var(--rstep) * 3);
}
.loader:nth-child(5) {
  --xdelay: calc(var(--rstep) * 4);
}
/* variations */
.light.primary {
  --dcolor: 152, 0, 257;
}
.light.secondary {
  --dcolor: 255, 255, 255;
}
.light.success {
  --dcolor: 25, 255, 80;
}
.light.warning {
  --dcolor: 247, 222, 57;
}
.light.danger {
  --dcolor: 255, 40, 40;
}
.light.info {
  --dcolor: 25, 202, 187;
}

.loader::after {
  content: var(--emessage, "Please wait");
  opacity: 0;
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: end;
  width: max-content;
  left: 40px;
  top: 1.4rem;
  font-family: "Inter", sans-serif;
  font-size: 0.8rem;
  color: #ffffff36;
  animation: message-anim var(--esequence) linear var(--plays) both;
  animation-delay: var(--xdelay);
}

.txt {
  display: inline-flex;
  font-size: 1.1rem;
  font-family: "Syne", "Inter", sans-serif;
  color: #eeede8;
  opacity: 0.2;
  user-select: none;
  animation: txt-anim var(--esequence) ease var(--plays) both;
  animation-delay: var(--xdelay);
}

.light {
  width: 16px;
  height: 16px;
  color: rgba(var(--dcolor), 0);
  background-color: currentColor;
  background-image: radial-gradient(circle at 50% 40%, #fff6 1px, currentColor);
  border-radius: 50%;
  border: 3px dotted #fff5;
  outline: 3px solid #0003;
  transition:
    background-color 400ms ease,
    color 400ms ease;
  box-shadow:
    1px 1px 2px 1px #0005 inset,
    -1px -1px 2px 1px #0005 inset,
    0 0 2px 1px currentColor,
    0 0 16px 0px currentColor,
    0 0 24px 3px currentColor,
    0 4px 8px 1px #0005,
    8px -16px 72px 8px rgba(255, 231, 201, 0.4);
  filter: drop-shadow(2px 0 0px #0006) drop-shadow(3px 6px 1px #0004)
    drop-shadow(4px 8px 32px currentColor)
    drop-shadow(-10px -10px 36px currentColor) contrast(1.1) brightness(1.3);
  animation: light-anim calc(var(--rstep) / var(--plays)) ease var(--plays) both;
  animation-delay: var(--xdelay);
}

@keyframes light-anim {
  0%,
  100% {
    color: rgba(var(--dcolor), 0);
  }

  50% {
    color: rgba(var(--dcolor), 1);
  }
}

@keyframes message-anim {
  0% {
    opacity: 0;
  }

  8%,
  20% {
    opacity: 1;
  }

  25%,
  100% {
    opacity: 0;
  }
}

@keyframes txt-anim {
  0% {
    opacity: 0.2;
  }

  8%,
  20% {
    opacity: 1;
  }

  25%,
  100% {
    opacity: 0.2;
  }
}
